import sys

SHAPES = {
    'Q': ((0, 0), (1, 0), (0, 1), (1, 1)),
    'Z': ((1, 0), (2, 0), (0, 1), (1, 1)),
    'S': ((0, 0), (1, 0), (1, 1), (2, 1)),
    'T': ((1, 0), (0, 1), (1, 1), (2, 1)),
    'I': ((0, 0), (1, 0), (2, 0), (3, 0)),
    'L': ((0, 0), (1, 0), (0, 1), (0, 2)),
    'J': ((0, 0), (1, 0), (1, 1), (1, 2)),
}
FULL = 1023


def height(line):
    rows = []        # one 10-bit mask per row, bottom row first
    top = [0] * 10   # top[c]: one above the highest occupied cell of column c
    for item in line.split(','):
        cells = SHAPES[item[0]]
        c = int(item[1])
        # The piece only meets the topmost block of each column on its way down.
        y = 0
        for dx, dy in cells:
            if top[c + dx] - dy > y:
                y = top[c + dx] - dy
        for dx, dy in cells:
            r = y + dy
            while len(rows) <= r:
                rows.append(0)
            rows[r] |= 1 << (c + dx)
            if top[c + dx] <= r:
                top[c + dx] = r + 1
        # Only rows touched by this piece can have become full.
        cleared = sum(1 for r in range(y, min(y + 3, len(rows))) if rows[r] == FULL)
        if cleared:
            rows = [r for r in rows if r != FULL]
            for col in range(10):
                t = top[col] - cleared
                while t > 0 and not rows[t - 1] >> col & 1:
                    t -= 1
                top[col] = t
        while rows and rows[-1] == 0:
            rows.pop()
    return len(rows)


def main():
    out = []
    for line in sys.stdin.read().splitlines():
        line = line.rstrip('\r')
        if line:
            out.append(str(height(line)))
    sys.stdout.write(''.join(s + '\n' for s in out))


